   FROM public.purchase_orders p
  WHERE ((p.id = purchase_order_items.purchase_order_id) AND (p.tenant_id IN ( SELECT public.current_tenant_ids() AS current_tenant_ids)))))) WITH CHECK ((EXISTS ( SELECT 1
   FROM public.purchase_orders p
  WHERE ((p.id = purchase_order_items.purchase_order_id) AND (p.tenant_id IN ( SELECT public.current_tenant_ids() AS current_tenant_ids))))));

